sp_widget.client_script:
api.controller = function($scope, $timeout, $window, $location, $element, spModal) {

  /* =========================================================
     GATENOW · APPLICANT INTAKE · Client script

     FIXES

     1. The flicker on Continue.
        nextStep() called saveDraft(), which called
        c.server.get(). Every server call re-runs the server
        script and replaces c.data, and Angular repaints the
        widget while that happens. What you saw as "a glimpse of
        the previous tab" was the widget rebuilding. Draft saving
        is gone, so Continue now only changes a number and
        nothing round trips.

     2. Uploads.
        The step used ng-file-upload (ngf-select / ngf-drop),
        which is not part of the Service Portal AngularJS bundle,
        so the directives never bound and nothing happened on
        click or drop. It now uses a native <input type="file">;
        this controller wires the change / drag / drop events
        itself once the documents step renders. The type check
        keeps its extension fallback, because a dragged or older
        .doc file often arrives with an empty or unexpected MIME
        type.

     3. Every field required.
        Middle name, organisation and the demographic selects are
        all validated. SSN is the single exception and is only
        required when the applicant type is Individual, since an
        organisation does not have one.

     4. Proposal step removed.
        The "Your proposal" step (title, description, goals,
        methodology, budget, dates) is gone from the wizard
        entirely. The five remaining steps are renumbered:
        Documents is now step 4, Review and submit is step 5.

     5. Submit no longer shows a success screen.
        done() used to hold a banner up for a countdown before
        redirecting. It now redirects straight to the status
        page. The earlier version of this also had a typo
        (c.data.Url instead of c.data.applicationStatusUrl) that
        would have thrown on every successful submit and left
        the applicant stuck - fixed below.

     6. Step rail desync (check+number both showing, highlight
        stuck on the wrong step).
        is-on, is-done, is-ahead and the check-vs-number mark
        used to each be computed inline in the template by
        calling c.isDone(s.n) / c.stepShowsCheck(s.n) separately
        in different bindings on every digest. That let the rail
        highlight and the check/number mark disagree with each
        other and with the panel. refreshStepFlags() now computes
        all four flags for every step, once per change, and
        stores them directly on the step object; the template
        binds to those stored flags instead of calling functions.
        c.stepShowsCheck is gone - nothing calls it anymore.
     ========================================================= */

  var c = this;

  var CONFIG = {
    MAX_FILE_SIZE: 10485760,
    TYPES: [
      'application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'image/jpeg', 'image/jpg', 'image/png'
    ],
    EXTS: ['.pdf', '.doc', '.docx', '.jpg', '.jpeg', '.png']
  };


  /* =====================================================
     DATES
     Parsed by hand so a value never shifts a day across a
     timezone boundary.
     ===================================================== */

  function toLocalDate(s) {
    if (!s || typeof s !== 'string') return s;
    var p = s.split('-');
    return p.length === 3 ? new Date(p[0], p[1] - 1, p[2]) : s;
  }

  function fromLocalDate(d) {
    if (!d || !(d instanceof Date) || isNaN(d)) return '';
    var m = d.getMonth() + 1;
    var day = d.getDate();
    return d.getFullYear() + '-' + (m < 10 ? '0' + m : m) + '-' + (day < 10 ? '0' + day : day);
  }

  function dateText(v) {
    if (!v) return '';
    return (v instanceof Date) ? fromLocalDate(v) : v;
  }


  /* =====================================================
     STATE

     Five steps now. Proposal is gone; Documents and Review
     shift down to fill 4 and 5.
     ===================================================== */

  c.steps = [
    { n: 1, label: c.data.t.s1, note: c.data.t.s1n },
    { n: 2, label: c.data.t.s2, note: c.data.t.s2n },
    { n: 3, label: c.data.t.s3, note: c.data.t.s3n },
    { n: 4, label: c.data.t.s5, note: c.data.t.s5n },
    { n: 5, label: c.data.t.s6, note: c.data.t.s6n }
  ];

  c.totalSteps     = c.steps.length;
  c.currentStep    = 1;
  c.completedSteps = [];
  c.errors         = {};
  c.saving         = false;
  c.uploadedFiles  = [];
  c.uploadProgress = 0;
  c.isDragging     = false;
  c.formBlocked    = false;
  c.draftResumed   = false;
  c.confirmed      = false;

  c.demoFields = [
    { key: 'gender',             label: c.data.t.gender },
    { key: 'race',               label: c.data.t.race },
    { key: 'ethnicity',          label: c.data.t.ethnicity },
    { key: 'education_level',    label: c.data.t.education },
    { key: 'marital_status',     label: c.data.t.marital },
    { key: 'military_status',    label: c.data.t.military },
    { key: 'disability_status',  label: c.data.t.disability },
    { key: 'tribal_affiliation', label: c.data.t.tribal }
  ];

  c.form = angular.merge({
    first_name: '', middle_name: '', last_name: '',
    email: '', phone_number: '', country: '',
    city: '', street: '', zip_postal_code: '',
    ssn: '', race: '', birthdate: '',
    uei: '', tin_ein: '',
    applicant_type: '', identity_type: '',
    gender: '', ethnicity: '',
    education_level: '', marital_status: '',
    military_status: '', disability_status: '',
    citizenship_status: '', tribal_affiliation: '',
    grant_program: '', program_category: '',
    organization: ''
  }, c.data.prefill || {});

  if (c.form.birthdate) c.form.birthdate = toLocalDate(c.form.birthdate);

  if (c.data.alreadySubmitted) c.formBlocked = true;

  if (!c.formBlocked && c.data.applicant_sys_id &&
      c.data.prefill && c.data.prefill.first_name) {
    c.draftResumed = true;
  }

  /* the program comes from the saved record first, then the URL */
  var target = (c.data.prefill && c.data.prefill.grant_program)
                 ? c.data.prefill.grant_program
                 : (c.data.program_param || '');

  $timeout(function() {
    if (target) c.form.grant_program = String(target).trim();
  });

  /* category is derived from the program, never typed */
  $scope.$watch(function() { return c.form.grant_program; }, function(val) {
    if (!val) { c.form.program_category = ''; return; }

    var list = c.data.programs || [];
    for (var i = 0; i < list.length; i++) {
      if (list[i].sys_id === val) {
        c.form.program_category = list[i].category || '';
        return;
      }
    }

    c.form.program_category = (c.data.prefill && c.data.prefill.program_category) || '';
  });


  /* =====================================================
     RAIL
     ===================================================== */

  c.stepTitle = function() {
    for (var i = 0; i < c.steps.length; i++) {
      if (c.steps[i].n === c.currentStep) return c.steps[i].label;
    }
    return '';
  };

  /* proposal's hint (h4) is skipped since that step no longer
     exists */
  c.stepHint = function() {
    var h = [c.data.t.h1, c.data.t.h2, c.data.t.h3, c.data.t.h5, c.data.t.h6];
    return h[c.currentStep - 1] || '';
  };

  c.isDone = function(n) { return c.completedSteps.indexOf(n) !== -1; };

  /* Single source of truth for the rail. Computes is-on, is-done,
     is-ahead and the check-vs-number mark for every step in one
     pass and stores them on the step object itself, so the rail
     highlight and the check/number mark are always reading the
     exact same values in the same digest - they can never
     disagree with each other or with the panel's c.currentStep. */
/* Single source of truth for the rail. Wrapped in $timeout to force 
     AngularJS to instantly repaint the blue highlight on the active step. */
function refreshStepFlags() {
    /* Create a deep copy of the array */
    var updatedSteps = angular.copy(c.steps);

    angular.forEach(updatedSteps, function(s) {
      s.done      = c.isDone(s.n);
      s.on        = Number(c.currentStep) === Number(s.n);
      s.ahead     = Number(s.n) > Number(c.currentStep) && !s.done;
      s.showCheck = s.done && !s.on;
    });

    /* Re-assigning the array inside a timeout forces Angular to instantly repaint the side rail */
    $timeout(function() {
      c.steps = updatedSteps;
    });
  }

  refreshStepFlags();

  c.progress = function() {
    return Math.round((c.completedSteps.length / c.totalSteps) * 100);
  };

  c.errorCount = function() {
    var n = 0;
    for (var k in c.errors) { if (c.errors.hasOwnProperty(k)) n++; }
    return n;
  };

  function programField(field) {
    var list = c.data.programs || [];
    for (var i = 0; i < list.length; i++) {
      if (list[i].sys_id === c.form.grant_program) return list[i][field] || '';
    }
    return '';
  }

  c.programName = function() { return programField('name'); };

  c.programMeta = function() {
    var bits = [];
    var num = programField('number');
    var cat = programField('category');
    if (num) bits.push(num);
    if (cat) bits.push(cat);
    return bits.join('  ·  ');
  };


  /* =====================================================
     VALIDATION
     Everything is required. SSN is the one exception, asked
     only of individual applicants. Proposal validation (old
     step 4) is gone. Documents is now step 4, Review is step 5.
     ===================================================== */

  function empty(v) {
    return v === undefined || v === null || v === '' ||
           (typeof v === 'string' && v.trim() === '');
  }

  c.validateStep = function(step) {
    c.errors = {};
    var ok = true;

    function need(field, msg) {
      if (empty(c.form[field])) { c.errors[field] = msg; ok = false; }
    }

if (step === 1) {
      need('first_name', c.data.t.eFirst);
      /* need('middle_name', c.data.t.eMiddle); -- REMOVED to make optional */
      need('last_name', c.data.t.eLast);

      if (empty(c.form.email)) { c.errors.email = c.data.t.eEmail; ok = false; }
      else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.form.email)) {
        c.errors.email = c.data.t.eEmailBad; ok = false;
      }

      need('phone_number', c.data.t.ePhone);
      need('birthdate', c.data.t.eDob);
      need('street', c.data.t.eStreet);
      need('city', c.data.t.eCity);
      need('zip_postal_code', c.data.t.eZip);
      need('country', c.data.t.eCountry);
    }

    else if (step === 2) {
      need('citizenship_status', c.data.t.eCitizen);

      /* An organisation does not have a social security number,
         so it is only demanded of individuals. Applicant type is
         chosen on step three, so a blank type does not block
         this step. */
      if (c.form.applicant_type === 'Individual') {
        need('ssn', c.data.t.eSsn);
      }

      for (var i = 0; i < c.demoFields.length; i++) {
        need(c.demoFields[i].key,
             c.demoFields[i].label + ' ' + c.data.t.eIsRequired);
      }
    }

    else if (step === 3) {
      need('grant_program', c.data.t.eProgram);
      need('applicant_type', c.data.t.eAType);
      need('organization', c.data.t.eOrg);
      need('identity_type', c.data.t.eIType);
      need('uei', c.data.t.eUei);
      need('tin_ein', c.data.t.eTin);
    }

    /* was step 5, is now step 4 */
    else if (step === 4) {
      if (!c.uploadedFiles.length) {
        c.errors.documents = c.data.t.eDocs; ok = false;
      }
    }

    /* was step 6, is now step 5 */
    else if (step === 5) {
      if (!c.uploadedFiles.length) {
        c.errors.documents = c.data.t.eDocs; ok = false;
      }
      if (!c.confirmed) {
        c.errors.confirmed = c.data.t.eConfirm; ok = false;
      }
    }

    if (!ok) scrollToErrors();

    return ok;
  };

  /* scoped to this widget rather than the whole document, so a
     second widget on the page cannot be scrolled to by mistake */
  function scrollToErrors() {
    $timeout(function() {
      var box = $element[0].querySelector('.gni-errors');
      if (box && box.scrollIntoView) {
        box.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }, 80);
  }


  /* =====================================================
     NAVIGATION
     No server call here. That was the flicker.
     ===================================================== */

  function toTop() {
    $timeout(function() {
      $window.scrollTo({ top: 0, behavior: 'smooth' });
    }, 60);
  }

  function markDone(step) {
    if (c.completedSteps.indexOf(step) === -1) c.completedSteps.push(step);
  }

  c.nextStep = function() {
    if (c.saving) return;
    if (!c.validateStep(c.currentStep)) return;
    markDone(c.currentStep);
    c.currentStep++;
    c.errors = {};
    refreshStepFlags();
    toTop();
  };

  c.prevStep = function() {
    if (c.currentStep <= 1 || c.saving) return;
    c.errors = {};
    c.currentStep--;
    refreshStepFlags();
    toTop();
  };

  c.goToStep = function(step) {
    if (c.formBlocked || c.saving) return;
    if (step < 1 || step > c.totalSteps || step === c.currentStep) return;

    /* back is always allowed, forward has to pass the step you
       are standing on */
    if (step > c.currentStep) {
      if (!c.validateStep(c.currentStep)) return;
      markDone(c.currentStep);
    }

    c.errors = {};
    c.currentStep = step;
    refreshStepFlags();
    toTop();
  };


  /* =====================================================
     REVIEW
     Proposal group (old step 4) is gone from the recap.
     ===================================================== */

  function row(label, value) { return { label: label, value: value }; }

  function choiceLabel(field, value) {
    var list = (c.data.choices || {})[field] || [];
    for (var i = 0; i < list.length; i++) {
      if (list[i].value === value) return list[i].label;
    }
    return value || '';
  }

  c.recap = function() {
    var f = c.form;

    return [
      {
        step: 1,
        title: c.data.t.s1,
        rows: [
          row(c.data.t.firstName, [f.first_name, f.middle_name, f.last_name].join(' ').replace(/\s+/g, ' ').trim()),
          row(c.data.t.email, f.email),
          row(c.data.t.phone, f.phone_number),
          row(c.data.t.birthdate, dateText(f.birthdate)),
          row(c.data.t.address, [f.street, f.city, f.zip_postal_code, f.country].filter(Boolean).join(', '))
        ]
      },
      {
        step: 2,
        title: c.data.t.s2,
        rows: [
          row(c.data.t.citizenship, choiceLabel('citizenship_status', f.citizenship_status)),
          row(c.data.t.gender, choiceLabel('gender', f.gender)),
          row(c.data.t.race, choiceLabel('race', f.race)),
          row(c.data.t.ethnicity, choiceLabel('ethnicity', f.ethnicity)),
          row(c.data.t.education, choiceLabel('education_level', f.education_level)),
          row(c.data.t.marital, choiceLabel('marital_status', f.marital_status)),
          row(c.data.t.military, choiceLabel('military_status', f.military_status)),
          row(c.data.t.disability, choiceLabel('disability_status', f.disability_status)),
          row(c.data.t.tribal, choiceLabel('tribal_affiliation', f.tribal_affiliation))
        ]
      },
      {
        step: 3,
        title: c.data.t.s3,
        rows: [
          row(c.data.t.program, c.programName()),
          row(c.data.t.category, f.program_category),
          row(c.data.t.applicantType, choiceLabel('applicant_type', f.applicant_type)),
          row(c.data.t.organisation, f.organization),
          row(c.data.t.identityType, choiceLabel('identity_type', f.identity_type)),
          row(c.data.t.uei, f.uei),
          row(c.data.t.tin, f.tin_ein)
        ]
      }
    ];
  };


  /* =====================================================
     FILES
     ===================================================== */

  /* A dragged file, and an older .doc, often arrive with an
     empty or unexpected type, which a strict MIME check rejects
     without saying why. The extension is the fallback. */
  function typeOk(file) {
    if (file.type && CONFIG.TYPES.indexOf(file.type) !== -1) return true;

    var name = (file.name || '').toLowerCase();
    for (var i = 0; i < CONFIG.EXTS.length; i++) {
      var ext = CONFIG.EXTS[i];
      if (name.length > ext.length && name.slice(-ext.length) === ext) return true;
    }
    return false;
  }

  function alreadyAdded(file) {
    for (var i = 0; i < c.uploadedFiles.length; i++) {
      var f = c.uploadedFiles[i];
      if (f.name === file.name && f.size === file.size) return true;
    }
    return false;
  }

  c.addFiles = function($files) {
    if (!$files || !$files.length) return;

    angular.forEach($files, function(file) {
      if (!file) return;

      if (file.size > CONFIG.MAX_FILE_SIZE) {
        spModal.open({
          title: c.data.t.tooBigTitle,
          message: '"' + file.name + '" ' + c.data.t.tooBigText,
          buttons: [{ label: c.data.t.ok, primary: true }]
        });
        return;
      }

      if (!typeOk(file)) {
        spModal.open({
          title: c.data.t.badTypeTitle,
          message: '"' + file.name + '" ' + c.data.t.badTypeText,
          buttons: [{ label: c.data.t.ok, primary: true }]
        });
        return;
      }

      /* choosing the same file twice would attach it twice */
      if (alreadyAdded(file)) return;

      c.uploadedFiles.push(file);
    });

    if (c.uploadedFiles.length) delete c.errors.documents;
  };

  c.removeFile = function(i) {
    if (i >= 0 && i < c.uploadedFiles.length) c.uploadedFiles.splice(i, 1);
  };

  c.formatFileSize = function(bytes) {
    if (!bytes) return '0 B';
    var k = 1024;
    var units = ['B', 'KB', 'MB', 'GB'];
    var i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round(bytes / Math.pow(k, i) * 10) / 10 + ' ' + units[i];
  };

  function toBase64(files) {
    var jobs = [];

    angular.forEach(files, function(file) {
      jobs.push(new Promise(function(resolve, reject) {
        var reader = new FileReader();

        reader.onload = function(e) {
          try {
            var parts = ('' + e.target.result).split(',');
            resolve({
              name: file.name,
              /* the server needs a type, and a dragged file may
                 not have one */
              type: file.type || 'application/octet-stream',
              size: file.size,
              data: parts.length > 1 ? parts[1] : parts[0]
            });
          } catch (err) { reject(err); }
        };

        reader.onerror = function() { reject('read failed: ' + file.name); };
        reader.readAsDataURL(file);
      }));
    });

    return Promise.all(jobs);
  }


  /* =====================================================
     FILE INPUT + DROPZONE WIRING
     Replaces ng-file-upload, which Service Portal does not
     bundle. The documents step lives inside an ng-if, so its
     DOM is built fresh each time the step opens; the listeners
     are therefore (re)attached whenever that step renders. The
     freshly-created element carries no bound flag, so it wires
     exactly once. Documents is now step 4.
     ===================================================== */

  c.pickFiles = function() {
    var input = $element[0].querySelector('.gni-file-input');
    if (input) input.click();
  };

  function bindDropzone() {
    var drop  = $element[0].querySelector('.gni-drop');
    var input = $element[0].querySelector('.gni-file-input');
    if (!drop || !input) return;

    if (drop.getAttribute('data-gni-bound') === '1') return;
    drop.setAttribute('data-gni-bound', '1');

    /* native picker */
    input.addEventListener('change', function(e) {
      var files = e.target.files;
      $scope.$apply(function() { c.addFiles(files); });
      /* clear so the same file can be re-picked after removal */
      e.target.value = '';
    });

    /* drag and drop */
    drop.addEventListener('dragover', function(e) {
      e.preventDefault();
      e.stopPropagation();
      if (!c.isDragging) $scope.$apply(function() { c.isDragging = true; });
    });

    drop.addEventListener('dragleave', function(e) {
      e.preventDefault();
      e.stopPropagation();
      if (c.isDragging) $scope.$apply(function() { c.isDragging = false; });
    });

    drop.addEventListener('drop', function(e) {
      e.preventDefault();
      e.stopPropagation();
      var files = (e.dataTransfer && e.dataTransfer.files) ? e.dataTransfer.files : null;
      $scope.$apply(function() {
        c.isDragging = false;
        if (files && files.length) c.addFiles(files);
      });
    });
  }

  $scope.$watch(function() { return c.currentStep; }, function(step) {
    if (step === 4) $timeout(bindDropzone);
  });


  /* =====================================================
     SUBMIT
     ===================================================== */

  function payload() {
    var p = angular.copy(c.form);

    p.birthdate = dateText(p.birthdate);

    p.action = 'save_applicant';
    p.applicant_sys_id = c.data.applicant_sys_id || '';

    return p;
  }

  c.submit = function() {
    if (c.saving) return;
    if (!c.validateStep(5)) return;

    c.saving = true;
    c.uploadProgress = 10;

    var p = payload();

    if (c.uploadedFiles.length) {
      toBase64(c.uploadedFiles).then(function(files) {
        /* the promise resolves outside a digest */
        $timeout(function() {
          p.attachments = files;
          c.uploadProgress = 55;
          send(p);
        });
      }, function() {
        $timeout(function() {
          c.saving = false;
          c.uploadProgress = 0;
          spModal.open({
            title: c.data.t.fileErrTitle,
            message: c.data.t.fileErrText,
            buttons: [{ label: c.data.t.ok, primary: true }]
          });
        });
      });
    } else {
      send(p);
    }
  };

  function send(p) {
    c.server.get(p).then(function(r) {
      var resp = (r && r.data) ? r.data : {};

      if (resp.success) {
        done();
      } else if (resp.alreadySubmitted) {
        c.formBlocked = true;
        done();
      } else {
        c.saving = false;
        c.uploadProgress = 0;
        spModal.open({
          title: c.data.t.submitErrTitle,
          message: resp.error || c.data.t.submitErrText,
          buttons: [{ label: c.data.t.ok, primary: true }]
        });
      }
    }, function() {
      c.saving = false;
      c.uploadProgress = 0;
      spModal.open({
        title: c.data.t.connErrTitle,
        message: c.data.t.connErrText,
        buttons: [{ label: c.data.t.ok, primary: true }]
      });
    });
  }

  /* no banner, no countdown - straight to the status page.
     c.data.Url was a typo in the previous version; the field
     the server script actually sets is applicationStatusUrl. */
  function done() {
    $location.url(c.data.applicationStatusUrl);
  }


  /* =====================================================
     CANCEL
     ===================================================== */

  c.cancel = function() {
    spModal.open({
      title: c.data.t.cancelTitle,
      message: c.data.t.cancelText,
      buttons: [
        { label: c.data.t.keepGoing, cancel: true },
        { label: c.data.t.discard, primary: true }
      ]
    }).then(function() {
      $location.url(c.data.applicationStatusUrl);
    });
  };

};

sp_widget.css:
/* =========================================================
   GATENOW · APPLICANT INTAKE
   Complete widget stylesheet (SCSS)

   This REPLACES the widget's CSS field in full. Paste the whole
   block; do not keep the old partial patch alongside it.

   It styles every class the HTML template emits, and folds in the
   four fixes from the patch (money alignment, the required note,
   the success-screen warning, the scrollable file list). The dead
   .gni-opt / .gni-saved rules are simply gone.

   THEME
   All colour/shape decisions live in the token block below as CSS
   custom properties. To share one look across every GateNow widget,
   lift that block into the Service Portal Theme's CSS as :root { ... }
   and delete it here — this sheet will then inherit it. Palette is
   the navy (#0a2540) you were already using, plus the amber warning
   tone, a success green, and an error red.
   ========================================================= */

.gni {

  /* ---------- theme tokens (lift to :root to share) ---------- */
  --gni-ink:        #0a2540;                 // primary navy
  --gni-ink-hover:  #14395e;                 // navy, one step lighter
  --gni-ink-90:     rgba(10, 37, 64, 0.90);
  --gni-ink-70:     rgba(10, 37, 64, 0.70);
  --gni-ink-54:     rgba(10, 37, 64, 0.54);
  --gni-ink-40:     rgba(10, 37, 64, 0.40);
  --gni-ink-16:     rgba(10, 37, 64, 0.16);
  --gni-ink-12:     rgba(10, 37, 64, 0.12);
  --gni-ink-10:     rgba(10, 37, 64, 0.10);
  --gni-ink-06:     rgba(10, 37, 64, 0.06);
  --gni-ink-04:     rgba(10, 37, 64, 0.04);

  // interactive blue — buttons, active step, progress, focus, links.
  // Text stays --gni-ink (above) so it keeps contrast. To go lighter
  // or darker, change these three; everything reroutes from here.
  --gni-brand:      #2563eb;                  // primary blue
  --gni-brand-hover:#1d4ed8;                  // one step darker (hover)
  --gni-brand-16:   rgba(37, 99, 235, 0.16);
  --gni-brand-10:   rgba(37, 99, 235, 0.10);
  --gni-brand-08:   rgba(37, 99, 235, 0.08);

  --gni-ok:         #1f8a52;                  // success green
  --gni-ok-bg:      rgba(31, 138, 82, 0.10);

  --gni-warn:       #8a6119;                  // amber (from the patch)
  --gni-warn-bd:    rgba(164, 116, 31, 0.30);
  --gni-warn-bg:    rgba(164, 116, 31, 0.09);

  --gni-err:        #c8372d;                  // error red
  --gni-err-bd:     rgba(200, 55, 45, 0.40);
  --gni-err-bg:     rgba(200, 55, 45, 0.07);

  --gni-surface:    #ffffff;
  --gni-canvas:     #f4f6f9;                  // page behind the card
  --gni-line:       rgba(10, 37, 64, 0.12);

  --gni-r-sm: 7px;
  --gni-r-md: 11px;
  --gni-r-lg: 16px;

  --gni-shadow: 0 1px 2px rgba(10, 37, 64, 0.06),
                0 10px 28px rgba(10, 37, 64, 0.06);

  /* ---------- root / reset ---------- */
  color: var(--gni-ink);
  font-family: inherit;                      // use the portal's font
  -webkit-font-smoothing: antialiased;
  background: var(--gni-canvas);             // remove if the page already paints one
  padding: 24px 16px 40px;

  *, *::before, *::after { box-sizing: border-box; }
  button { font-family: inherit; }

  /* =======================================================
     STATE SCREENS · blocked + success
     ======================================================= */
  .gni-block,
  .gni-done {
    max-width: 560px;
    margin: 40px auto;
    padding: 40px 32px;
    text-align: center;
    background: var(--gni-surface);
    border: 1px solid var(--gni-line);
    border-radius: var(--gni-r-lg);
    box-shadow: var(--gni-shadow);
  }

  .gni-block__mark,
  .gni-done__mark {
    display: grid;
    place-items: center;
    width: 56px;
    height: 56px;
    margin: 0 auto 20px;
    border-radius: 50%;
    font-size: 24px;
  }
  .gni-block__mark { background: var(--gni-ink-06); color: var(--gni-ink); }
  .gni-done__mark  { background: var(--gni-brand-08); color: var(--gni-brand); }

  .gni-block__title,
  .gni-done__title {
    margin: 0 0 10px;
    font-size: 22px;
    font-weight: 700;
    line-height: 1.25;
  }

  .gni-block__text,
  .gni-done__text {
    margin: 0 0 22px;
    font-size: 14px;
    line-height: 1.6;
    color: var(--gni-ink-70);
  }
  .gni-done__text strong { color: var(--gni-ink); font-weight: 700; }

  /* success warning — record saved, attachments did not (patch #4) */
  .gni-done__warn {
    margin: 14px 0 22px;
    padding: 12px 16px;
    border: 1px solid var(--gni-warn-bd);
    border-radius: var(--gni-r-md);
    background: var(--gni-warn-bg);
    font-size: 13.5px;
    line-height: 1.6;
    color: var(--gni-warn);
    text-align: left;
  }

  /* =======================================================
     LAYOUT · wrap, context header, body
     ======================================================= */
  .gni-wrap { max-width: 1080px; margin: 0 auto; }

  .gni-context {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 16px;
    margin: 0 0 24px;
  }
  .gni-context__label {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--gni-ink-54);
  }
  .gni-context__name {
    margin: 4px 0 0;
    font-size: 22px;
    font-weight: 700;
    line-height: 1.2;
  }
  .gni-context__meta {
    margin: 4px 0 0;
    font-size: 13px;
    color: var(--gni-ink-54);
  }

  .gni-body {
    display: grid;
    grid-template-columns: 264px 1fr;
    gap: 28px;
    align-items: start;
  }

  /* =======================================================
     STEP RAIL + PROGRESS
     ======================================================= */
  .gni-rail { position: sticky; top: 16px; }

  .gni-rail__label {
    margin: 0 0 10px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--gni-ink-54);
  }

  .gni-steps {
    margin: 0;
    padding: 0;
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 4px;
  }

  .gni-step {
    display: flex;
    align-items: center;
    gap: 12px;
    width: 100%;
    padding: 10px;
    text-align: left;
    background: none;
    border: none;
    border-radius: var(--gni-r-md);
    cursor: pointer;
    transition: background 0.15s;

    &:hover { background: var(--gni-ink-04); }
    &:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--gni-brand-16); }
  }
  .gni-step__mark {
    flex: 0 0 28px;
    height: 28px;
    display: grid;
    place-items: center;
    border-radius: 50%;
    border: 1.5px solid var(--gni-line);
    background: var(--gni-surface);
    color: var(--gni-ink-54);
    font-size: 12px;
    font-weight: 700;

    /* Defensive fallback: the check icon and the step-number span
       are meant to be template-level mutually exclusive (bound to
       the single s.showCheck flag computed in the client script).
       This rule is a belt-and-suspenders guard so that if the two
       ever end up in the DOM together, the number never shows on
       top of / underneath the check. */
    i.fa-check + span { display: none; }
  }
  .gni-step__body { display: flex; flex-direction: column; min-width: 0; }
  .gni-step__name { font-size: 13.5px; font-weight: 600; color: var(--gni-ink-70); }
  .gni-step__note { font-size: 12px; color: var(--gni-ink-40); }

  .gni-step.is-on {
    background: var(--gni-brand-08);
    .gni-step__mark { background: var(--gni-brand); border-color: var(--gni-brand); color: #fff; }
    .gni-step__name { color: var(--gni-ink); }
  }
  .gni-step.is-done .gni-step__mark {
    background: var(--gni-brand);
    border-color: var(--gni-brand);
    color: #fff;
  }
  .gni-step.is-ahead { opacity: 0.72; }

  .gni-rail__foot {
    margin-top: 16px;
    padding-top: 16px;
    border-top: 1px solid var(--gni-line);
  }
  .gni-rail__track {
    display: block;
    height: 6px;
    border-radius: 999px;
    background: var(--gni-ink-10);
    overflow: hidden;
  }
  .gni-rail__fill {
    display: block;
    height: 100%;
    border-radius: 999px;
    background: var(--gni-brand);
    transition: width 0.3s ease;
  }
  .gni-rail__pct {
    display: block;
    margin-top: 8px;
    font-size: 12px;
    font-weight: 600;
    color: var(--gni-ink-54);
  }

  /* =======================================================
     PANEL
     ======================================================= */
  .gni-panel {
    padding: 28px 30px;
    background: var(--gni-surface);
    border: 1px solid var(--gni-line);
    border-radius: var(--gni-r-lg);
    box-shadow: var(--gni-shadow);
  }

  .gni-resumed {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0 0 18px;
    padding: 10px 14px;
    border: 1px solid var(--gni-ink-10);
    border-radius: var(--gni-r-md);
    background: var(--gni-ink-04);
    font-size: 13px;
    color: var(--gni-ink-70);

    i { color: var(--gni-ink-54); }
  }

  .gni-panel__head {
    margin-bottom: 22px;
    padding-bottom: 20px;
    border-bottom: 1px solid var(--gni-line);
  }
  .gni-panel__count {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--gni-ink-40);
  }
  .gni-panel__title { margin: 6px 0 0; font-size: 20px; font-weight: 700; }
  .gni-panel__hint  { margin: 6px 0 0; font-size: 13.5px; line-height: 1.55; color: var(--gni-ink-70); }

  /* "every field is required" note (patch #3) */
  .gni-panel__req {
    display: inline-flex;
    align-items: center;
    margin: 14px 0 0;
    padding: 5px 11px;
    border-radius: var(--gni-r-sm);
    background: var(--gni-ink-04);
    font-size: 12px;
    font-weight: 500;
    color: var(--gni-ink-54);
  }

  /* error summary box */
  .gni-errors {
    margin: 0 0 20px;
    padding: 14px 16px;
    border: 1px solid var(--gni-err-bd);
    border-radius: var(--gni-r-md);
    background: var(--gni-err-bg);
  }
  .gni-errors__title { margin: 0 0 8px; font-size: 13.5px; font-weight: 700; color: var(--gni-err); }
  .gni-errors__list  { margin: 0; padding-left: 18px; }
  .gni-errors__list li { font-size: 13px; line-height: 1.5; color: var(--gni-err); }

  /* =======================================================
     FIELDS · 12-column grid
     ======================================================= */
  .gni-fields {
    display: grid;
    grid-template-columns: repeat(12, 1fr);
    gap: 18px 16px;
    align-items: start;
  }

  .gni-field         { display: flex; flex-direction: column; grid-column: span 12; }
  .gni-field--full   { grid-column: span 12; }
  .gni-field--half   { grid-column: span 6; }
  .gni-field--third  { grid-column: span 4; }
  .gni-field--quarter{ grid-column: span 3; }

  .gni-field label {
    margin-bottom: 6px;
    font-size: 13px;
    font-weight: 600;
    color: var(--gni-ink-70);
  }

  .gni-field input,
  .gni-field select,
  .gni-field textarea {
    width: 100%;
    padding: 10px 12px;
    font-size: 14px;
    line-height: 1.4;
    color: var(--gni-ink);
    background: var(--gni-surface);
    border: 1px solid var(--gni-line);
    border-radius: var(--gni-r-sm);
    transition: border-color 0.15s, box-shadow 0.15s;

    &::placeholder { color: var(--gni-ink-40); }

    &:focus {
      outline: none;
      border-color: var(--gni-brand);
      box-shadow: 0 0 0 3px var(--gni-brand-10);
    }

    &.has-error {
      border-color: var(--gni-err-bd);
      &:focus { box-shadow: 0 0 0 3px var(--gni-err-bg); }
    }
  }

  .gni-field textarea { min-height: 96px; resize: vertical; }

  /* select wrapper + chevron */
  .gni-pick { position: relative; }
  .gni-pick select {
    appearance: none;
    -webkit-appearance: none;
    padding-right: 36px;
    cursor: pointer;
  }
  .gni-pick i {
    position: absolute;
    top: 50%;
    right: 14px;
    transform: translateY(-50%);
    color: var(--gni-ink-54);
    font-size: 14px;
    pointer-events: none;
  }

  /* money field (patch #1 — sign at 14, padding at 32) */
  .gni-money { position: relative; }
  .gni-money__sign {
    position: absolute;
    top: 50%;
    left: 14px;
    transform: translateY(-50%);
    color: var(--gni-ink-54);
    font-size: 14px;
    pointer-events: none;
  }
  .gni-money input { padding-left: 32px; }

  /* helper + inline error text */
  .gni-note { margin-top: 6px; font-size: 12px; color: var(--gni-ink-54); }
  .gni-err  { margin-top: 6px; font-size: 12.5px; font-weight: 500; color: var(--gni-err); }

  /* sub-heading inside a field grid (e.g. Address, Budget and timing) */
  .gni-sub {
    grid-column: 1 / -1;
    margin: 8px 0 -4px;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--gni-ink-54);
  }

  /* "why we ask" explainer block */
  .gni-explain {
    grid-column: 1 / -1;
    padding: 14px 16px;
    border: 1px solid var(--gni-ink-10);
    border-radius: var(--gni-r-md);
    background: var(--gni-ink-04);
  }
  .gni-explain__title { margin: 0; font-size: 13px; font-weight: 700; color: var(--gni-ink); }
  .gni-explain__text  { margin: 4px 0 0; font-size: 13px; line-height: 1.55; color: var(--gni-ink-70); }

  /* =======================================================
     DOCUMENTS · drop zone + file list
     ======================================================= */
  /* Native input is driven programmatically via c.pickFiles(); kept in
     the DOM but visually hidden. Not display:none, because some browsers
     won't fire a programmatic .click() on a display:none input. */
  .gni-file-input {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    border: 0;
    overflow: hidden;
    clip: rect(0 0 0 0);
    opacity: 0;
  }

  .gni-drop {
    padding: 32px 24px;
    text-align: center;
    border: 2px dashed var(--gni-line);
    border-radius: var(--gni-r-lg);
    background: var(--gni-ink-04);
    transition: border-color 0.15s, background 0.15s;

    &.is-over   { border-color: var(--gni-brand); background: var(--gni-brand-08); }
    &.has-error { border-color: var(--gni-err-bd); }
  }
  .gni-drop__mark  { font-size: 32px; color: var(--gni-ink-40); }
  .gni-drop__title { margin: 12px 0 0; font-size: 16px; font-weight: 700; }
  .gni-drop__text  { margin: 4px 0 16px; font-size: 13px; color: var(--gni-ink-54); }
  .gni-drop__btn   { margin: 0 auto; }

  /* a long list scrolls rather than pushing submit off-screen (patch #5) */
  .gni-files {
    margin: 16px 0 0;
    padding: 0;
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 8px;
    max-height: 320px;
    overflow-y: auto;
  }
  .gni-file {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 12px;
    border: 1px solid var(--gni-line);
    border-radius: var(--gni-r-md);
    background: var(--gni-surface);
  }
  .gni-file__mark { flex: 0 0 auto; font-size: 16px; color: var(--gni-ink-54); }
  .gni-file__body { flex: 1; min-width: 0; display: flex; flex-direction: column; }
  .gni-file__name {
    font-size: 13.5px;
    font-weight: 600;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .gni-file__size { font-size: 12px; color: var(--gni-ink-54); }
  .gni-file__x {
    flex: 0 0 auto;
    display: grid;
    place-items: center;
    width: 28px;
    height: 28px;
    border: none;
    border-radius: 50%;
    background: none;
    color: var(--gni-ink-54);
    cursor: pointer;
    transition: background 0.15s, color 0.15s;

    &:hover { background: var(--gni-err-bg); color: var(--gni-err); }
  }

  /* =======================================================
     REVIEW · recap + confirm
     ======================================================= */
  .gni-review { display: flex; flex-direction: column; gap: 16px; }

  .gni-recap {
    padding: 18px 20px;
    border: 1px solid var(--gni-line);
    border-radius: var(--gni-r-md);
  }
  .gni-recap__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
  }
  .gni-recap__title { margin: 0; font-size: 15px; font-weight: 700; }
  .gni-recap__edit {
    padding: 4px 10px;
    border: none;
    border-radius: var(--gni-r-sm);
    background: none;
    color: var(--gni-brand);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;

    &:hover { background: var(--gni-brand-08); }
  }
  .gni-recap__rows { margin: 0; display: flex; flex-direction: column; gap: 10px; }
  .gni-recap__row {
    display: grid;
    grid-template-columns: 180px 1fr;
    gap: 12px;
    align-items: baseline;
  }
  .gni-recap__row dt { margin: 0; font-size: 13px; font-weight: 600; color: var(--gni-ink-54); }
  .gni-recap__row dd { margin: 0; font-size: 13.5px; color: var(--gni-ink); word-break: break-word; }
  .gni-recap__row dd.is-blank,
  .gni-recap__files.is-blank { color: var(--gni-ink-40); font-style: italic; }
  .gni-recap__files { margin: 0; font-size: 13.5px; }

  .gni-confirm {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    margin: 0;
    padding: 16px 18px;
    border: 1px solid var(--gni-line);
    border-radius: var(--gni-r-md);
    background: var(--gni-ink-04);
    cursor: pointer;

    input {
      flex: 0 0 auto;
      width: 16px;
      height: 16px;
      margin-top: 2px;
      accent-color: var(--gni-brand);
    }
    span { font-size: 13.5px; line-height: 1.5; color: var(--gni-ink-70); }
  }

  /* =======================================================
     ACTIONS + upload progress
     ======================================================= */
  .gni-actions {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-top: 26px;
    padding-top: 22px;
    border-top: 1px solid var(--gni-line);
  }
  .gni-actions__right { display: flex; gap: 10px; }

  .gni-progressbar {
    position: relative;
    height: 4px;
    margin-top: 16px;
    border-radius: 999px;
    background: var(--gni-ink-10);
    overflow: hidden;

    span {
      position: absolute;
      top: 0;
      left: 0;
      height: 100%;
      border-radius: 999px;
      background: var(--gni-brand);
      transition: width 0.3s ease;
    }
  }

  /* =======================================================
     BUTTONS
     ======================================================= */
  .gni-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 10px 18px;
    font-size: 14px;
    font-weight: 600;
    line-height: 1.2;
    white-space: nowrap;
    text-decoration: none;
    border: 1px solid transparent;
    border-radius: var(--gni-r-sm);
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s, color 0.15s, box-shadow 0.15s;

    &:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--gni-brand-16); }
    &:disabled { opacity: 0.5; cursor: not-allowed; }
  }
  .gni-btn--primary {
    background: var(--gni-brand);
    color: #fff;
    &:hover:not(:disabled) { background: var(--gni-brand-hover); }
  }
  .gni-btn--ghost {
    background: var(--gni-surface);
    border-color: var(--gni-line);
    color: var(--gni-ink);
    &:hover:not(:disabled) { background: var(--gni-ink-04); border-color: var(--gni-ink-40); }
  }
  .gni-btn--quiet {
    padding: 8px 12px;
    background: none;
    color: var(--gni-ink-54);
    &:hover:not(:disabled) { background: var(--gni-ink-04); color: var(--gni-ink); }
  }

  /* =======================================================
     RESPONSIVE
     ======================================================= */
  @media (max-width: 880px) {
    .gni-body { grid-template-columns: 1fr; }

    .gni-rail { position: static; }
    .gni-rail__label { display: none; }
    .gni-steps {
      flex-direction: row;
      flex-wrap: nowrap;
      overflow-x: auto;
      gap: 6px;
      -webkit-overflow-scrolling: touch;
    }
    .gni-step { flex: 0 0 auto; padding: 8px 10px; }
    .gni-step__note { display: none; }
  }

  @media (max-width: 760px) {
    .gni-field--third,
    .gni-field--quarter { grid-column: span 6; }
  }

  @media (max-width: 640px) {
    .gni-panel { padding: 20px 18px; }

    .gni-context { flex-direction: column; align-items: flex-start; }

    .gni-field--half,
    .gni-field--third,
    .gni-field--quarter { grid-column: span 12; }

    .gni-recap__row { grid-template-columns: 1fr; gap: 2px; }

    .gni-actions { flex-direction: column-reverse; align-items: stretch; }
    .gni-actions__right { flex-direction: column; }
    .gni-btn { width: 100%; }
  }

  /* respect reduced-motion */
  @media (prefers-reduced-motion: reduce) {
    * { transition: none !important; }
  }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW · APPLICANT INTAKE · Server script

     WHY THIS IS A FULL REPLACEMENT

     The version in use was marked READ ONLY and had no save
     actions in it at all. So the submit button posted a payload
     that nothing handled, which is why attachments never
     arrived: there was no code to write them. That is the same
     reason the draft save was doing nothing useful except
     forcing a widget re-render, which is the flicker.

     Three field name corrections while I was in here:

       grant_program  ->  program
           The applicant table field is program. Querying and
           prefilling grant_program silently matched nothing, so
           no draft was ever found.

       name           ->  program_name
           On the grant program table. Reading name returned
           empty, which is why the program dropdown rendered a
           list of blank options.

       submitted      ->  state
           There is no submitted field. Whether an application
           has gone in is held in state.

     The program is also read from either URL parameter, because
     the program detail page sends sys_id and the older links
     send program.
     ========================================================= */

  var APPLICANT = 'x_enno_gatenow_service_applicants';
  var PROGRAM   = 'x_enno_gatenow_grant_program';

  var currentUser = gs.getUserID();

  data.success          = false;
  data.error            = '';
  data.message          = '';
  data.alreadySubmitted = false;

  if (typeof input === 'undefined' || input === null) input = {};


  /* ---------- helpers ---------- */

  function param(key, dflt) {
    try {
      if (input && input[key] !== undefined && input[key] !== null) return input[key];
    } catch (e) { /* fall through */ }
    return dflt;
  }

  function cleanDate(v) {
    if (!v) return '';
    v = String(v);
    if (v.indexOf('T') > -1) return v.split('T')[0];
    var m = v.match(/\d{4}-\d{2}-\d{2}/);
    return m ? m[0] : v;
  }

  function programRef() {
    return String(param('grant_program', '') || param('program', '') || '');
  }


  /* ---------- which program ----------
     The detail page hands over sys_id. Older links use program.
     Either is accepted so a bookmarked URL still works. */
  var programParam = $sp.getParameter('program') || $sp.getParameter('sys_id') || '';
  data.program_param = programParam;

  var actionVal = String(param('action', ''));


  /* ---------- lookups ---------- */

  function alreadyIn(userId, programId) {
    if (!userId || !programId) return false;
    var gr = new GlideRecordSecure(APPLICANT);
    gr.addQuery('user', userId);
    gr.addQuery('program', programId);
    /* anything past draft counts as submitted */
    gr.addQuery('state', '!=', 'draft');
    gr.query();
    return gr.hasNext();
  }

  function findDraft(userId, programId) {
    if (!userId || !programId) return '';
    var gr = new GlideRecordSecure(APPLICANT);
    gr.addQuery('user', userId);
    gr.addQuery('program', programId);
    gr.addQuery('state', 'draft');
    gr.orderByDesc('sys_updated_on');
    gr.setLimit(1);
    gr.query();
    return gr.next() ? gr.getUniqueValue() : '';
  }

  /* category is never taken from the form, it is read off the
     program so the two can never disagree */
function categoryOf(programId) {
  if (!programId) return '';
  var gr = new GlideRecordSecure(PROGRAM);
  if (gr.get(programId)) {
    return gr.getValue('category') || '';
  }
  return '';
}


  /* ---------- write ---------- */

  function mapFields(rec) {

    var text = [
      'first_name', 'middle_name', 'last_name', 'email', 'phone_number',
      'street', 'city', 'zip_postal_code', 'country',
      'ssn', 'gender', 'race', 'ethnicity', 'education_level',
      'marital_status', 'military_status', 'disability_status',
      'citizenship_status', 'tribal_affiliation',
      'applicant_type', 'identity_type', 'uei', 'tin_ein', 'organization',

    ];

    for (var i = 0; i < text.length; i++) {
      rec.setValue(text[i], param(text[i], ''));
    }

    var bd = cleanDate(param('birthdate', ''));
    if (bd) rec.setValue('birthdate', bd);


    var prog = programRef();
    if (prog) {
      rec.setValue('program', prog);
      rec.setValue('program_category', categoryOf(prog));
    }

    rec.setValue('user', currentUser);
    if (rec.isValidField('submitted_by')) rec.setValue('submitted_by', currentUser);
  }

  function attach(sysId, files) {
    if (!files || !files.length) return 0;

    var rec = new GlideRecordSecure(APPLICANT);
    if (!rec.get(sysId)) return 0;

    var done = 0;

    for (var i = 0; i < files.length; i++) {
      var f = files[i];
      if (!f || !f.data) continue;
      try {
        var id = new GlideSysAttachment().writeBase64(rec, f.name, f.type, f.data);
        if (id) done++;
        else gs.error('[Intake] attachment rejected: ' + f.name);
      } catch (e) {
        gs.error('[Intake] attachment failed on ' + f.name + ': ' + e.message);
      }
    }

    return done;
  }


  /* ============================================================
     ACTION · SUBMIT
     ============================================================ */
  if (actionVal === 'save_applicant') {
    try {

      var prog = programRef();

      if (alreadyIn(currentUser, prog)) {
        data.alreadySubmitted = true;
        data.error = gs.getMessage('You have already applied to this program.');
        return;
      }

      var gr = new GlideRecordSecure(APPLICANT);
      var target = String(param('applicant_sys_id', ''));
      var isUpdate = false;

      if (target && gr.get(target)) {
        isUpdate = true;
      } else {
        gr.initialize();
      }

      mapFields(gr);
      gr.setValue('state', 'new');

      if (!isUpdate) {
        gr.setValue('submission_date', new GlideDateTime().getValue());
      }

      var savedId = isUpdate ? gr.update() : gr.insert();

      if (!savedId) {
        data.error = gs.getMessage('The application could not be saved. Nothing was lost, try again.');
        return;
      }

      var files = param('attachments', []);
      var attached = attach(savedId, files);

      if (files && files.length && attached === 0) {
        /* the record is in, but the applicant needs to know the
           documents are not */
        data.error = gs.getMessage('Your application was saved but the documents did not attach. Open the application from your dashboard and add them.');
      }

      data.success          = true;
      data.applicant_sys_id = String(savedId);
      data.attachedCount    = attached;
      data.message          = gs.getMessage('Application submitted');

    } catch (e) {
      gs.error('[Intake] submit failed: ' + e.toString());
      data.error = gs.getMessage('Something went wrong submitting the application.') + ' ' + e.message;
    }
  }


  /* ============================================================
     PAGE LOAD
     ============================================================ */
  if (!actionVal) {

    if (programParam && alreadyIn(currentUser, programParam)) {
      data.alreadySubmitted = true;
      data.error = gs.getMessage('You have already applied to this program.');
    }

    if (programParam && !data.alreadySubmitted) {
      data.applicant_sys_id = findDraft(currentUser, programParam);
    }
  }


  /* ============================================================
     PREFILL
     ============================================================ */
  data.prefill = {};

  if (data.applicant_sys_id) {
    var p = new GlideRecordSecure(APPLICANT);
    if (p.get(data.applicant_sys_id)) {

      var read = [
        'first_name', 'middle_name', 'last_name', 'email', 'phone_number',
        'street', 'city', 'zip_postal_code', 'country', 'birthdate',
        'ssn', 'gender', 'race', 'ethnicity', 'education_level',
        'marital_status', 'military_status', 'disability_status',
        'citizenship_status', 'tribal_affiliation',
        'applicant_type', 'identity_type', 'uei', 'tin_ein', 'organization',
        'program_category'
      ];

      for (var r = 0; r < read.length; r++) {
        data.prefill[read[r]] = p.getValue(read[r]) || '';
      }

      /* the form field is called grant_program, the column is
         program */
      data.prefill.grant_program = p.getValue('program') || programParam || '';
    }
  }

  if (!data.prefill.grant_program && programParam) {
    data.prefill.grant_program = programParam;
  }


  /* ============================================================
     PROGRAMS
     program_name, not name. Reading name returned empty, which
     is why the dropdown was a list of blanks.
     ============================================================ */
  data.programs = [];

  var pg = new GlideRecordSecure(PROGRAM);
  pg.addQuery('active', true);
  pg.orderBy('program_name');
  pg.query();

  while (pg.next()) {
    data.programs.push({
      sys_id  : pg.getUniqueValue(),
      name    : pg.getValue('program_name') || pg.getValue('number'),
      number  : pg.getValue('number') || '',
      category: pg.getValue('category') || ''
    });
  }


  /* ============================================================
     CHOICES
     Read from the dictionary first so the form can never drift
     from the table. The declared list is only a fallback for
     when sys_choice is not readable by this user, which is
     common for external accounts.

     ADJUST the fallback values if any of them differ from the
     dictionary, because a wrong value saves an empty field
     without complaining.
     ============================================================ */

  var FALLBACK = {
    applicant_type: [
      { value: 'Government',   label: 'Government' },
      { value: 'Individual',   label: 'Individual' },
      { value: 'Organization', label: 'Organization' }
    ],
    citizenship_status: [
      { value: 'Citizen',            label: 'Citizen' },
      { value: 'Non-Immigrant',      label: 'Non-Immigrant' },
      { value: 'Permanent Resident', label: 'Permanent Resident' },
      { value: 'Undocumented',       label: 'Undocumented' }
    ],
    disability_status: [
      { value: 'yes',         label: 'Yes, I have a disability' },
      { value: 'no',          label: 'No, I do not have a disability' },
      { value: 'do_not_wish', label: 'I do not wish to provide this information' }
    ],
    education_level: [
      { value: 'Associate degree',                     label: 'Associate degree' },
      { value: 'bachelor_degree',                      label: "Bachelor's degree" },
      { value: 'Doctorate',                            label: 'Doctorate' },
      { value: 'High school or equivalent',            label: 'High school or equivalent' },
      { value: 'Masters degree',                       label: "Master's degree" },
      { value: 'Professional',                         label: 'Professional' },
      { value: 'Some college coursework completed',    label: 'Some college coursework completed' },
      { value: 'Technical or occupational certificate', label: 'Technical or occupational certificate' },
      { value: 'Other',                                label: 'Other' }
    ],
    ethnicity: [
      { value: 'Hispanic or Latino',     label: 'Hispanic or Latino' },
      { value: 'Not Hispanic or Latino', label: 'Not Hispanic or Latino' },
      { value: 'I do not wish to provide this information', label: 'I do not wish to provide this information' }
    ],
    gender: [
      { value: 'Female', label: 'Female' },
      { value: 'Male',   label: 'Male' },
      { value: 'Other',  label: 'Other' }
    ],
    identity_type: [
      { value: "Driver's License Number",     label: "Driver's License Number" },
      { value: 'Medicare Number',             label: 'Medicare Number' },
      { value: 'Social Security Number',      label: 'Social Security Number' },
      { value: 'State Identification Number', label: 'State Identification Number' }
    ],
    marital_status: [
      { value: 'Single',   label: 'Single' },
      { value: 'Married',  label: 'Married' },
      { value: 'Divorced', label: 'Divorced' },
      { value: 'Widowed',  label: 'Widowed' }
    ],
    military_status: [
      { value: 'active_duty',       label: 'Active duty' },
      { value: 'veterans',          label: 'Veteran' },
      { value: 'no_military_duty',  label: 'No military duty' },
      { value: 'i_do_not_wish_to_provide_this_information', label: 'I do not wish to provide this information' }
    ],
    race: [
      { value: 'American Indian or Alaska Native',          label: 'American Indian or Alaska Native' },
      { value: 'Asian',                                     label: 'Asian' },
      { value: 'Black or African American',                 label: 'Black or African American' },
      { value: 'Native Hawaiian or Other pacific Islander',  label: 'Native Hawaiian or Other Pacific Islander' },
      { value: 'White',                                     label: 'White' },
      { value: 'I do not wish to provide this informantion', label: 'I do not wish to provide this information' }
    ],
    tribal_affiliation: [
      { value: 'Yes', label: 'Yes' },
      { value: 'No',  label: 'No' }
    ]
  };

  function choicesFor(element) {

    var out = [];

    try {
      var ch = new GlideRecordSecure('sys_choice');
      ch.addQuery('name', APPLICANT);
      ch.addQuery('element', element);

      /* language is often blank on scoped choices, and inactive
         is frequently null rather than false. Both were being
         filtered out before, which returned nothing. */
      var lang = ch.addQuery('language', 'en');
      lang.addOrCondition('language', '');
      lang.addOrCondition('language', 'NULL');

      var act = ch.addQuery('inactive', false);
      act.addOrCondition('inactive', '');

      ch.orderBy('sequence');
      ch.orderBy('label');
      ch.query();

      while (ch.next()) {
        var v = ch.getValue('value');
        if (v === null || v === undefined || v === '') continue;
        out.push({ value: v, label: ch.getValue('label') || v });
      }
    } catch (e) {
      gs.info('[Intake] sys_choice not readable for ' + element + ': ' + e.message);
    }

    if (!out.length) {
      out = FALLBACK[element] || [];
      gs.info('[Intake] using declared choices for ' + element);
    }

    return out;
  }

  data.choices = {
    applicant_type    : choicesFor('applicant_type'),
    identity_type     : choicesFor('identity_type'),
    gender            : choicesFor('gender'),
    race              : choicesFor('race'),
    ethnicity         : choicesFor('ethnicity'),
    education_level   : choicesFor('education_level'),
    marital_status    : choicesFor('marital_status'),
    military_status   : choicesFor('military_status'),
    disability_status : choicesFor('disability_status'),
    citizenship_status: choicesFor('citizenship_status'),
    tribal_affiliation: choicesFor('tribal_affiliation')
  };


  /* ============================================================
     COPY
     ============================================================ */
  data.applicationStatusUrl = '/applicant?id=application_status';

  data.t = {
    applyingTo   : gs.getMessage('Applying to'),
    noProgram    : gs.getMessage('No program selected yet'),
    cancel       : gs.getMessage('Cancel'),
    steps        : gs.getMessage('Steps'),
    step         : gs.getMessage('Step'),
    of           : gs.getMessage('of'),
    complete     : gs.getMessage('complete'),
    allRequired  : gs.getMessage('Every field on this step is required'),
    resumed      : gs.getMessage('We picked up where you left off. Everything you had filled in is still here.'),
    errorsFound  : gs.getMessage('things still need attention'),
    choose       : gs.getMessage('Choose one'),
    charsLeft    : gs.getMessage('characters left'),
    notGiven     : gs.getMessage('Not given'),
    edit         : gs.getMessage('Edit'),

    s1  : gs.getMessage('About you'),
    s1n : gs.getMessage('Name and contact'),
    s2  : gs.getMessage('Background'),
    s2n : gs.getMessage('For funder reporting'),
    s3  : gs.getMessage('Organisation'),
    s3n : gs.getMessage('Program and identifiers'),
    s4  : gs.getMessage('Your proposal'),
    s4n : gs.getMessage('The part only you can write'),
    s5  : gs.getMessage('Documents'),
    s5n : gs.getMessage('Attach your evidence'),
    s6  : gs.getMessage('Review and submit'),
    s6n : gs.getMessage('Last look before it goes'),

    h1 : gs.getMessage('Who the review team should contact about this application.'),
    h2 : gs.getMessage('Funders report on who their programs reach. None of it affects how your application is scored.'),
    h3 : gs.getMessage('Which program you are applying to, and how your organisation is identified.'),
    h4 : gs.getMessage('The project itself. Take your time here, this is what gets scored.'),
    h5 : gs.getMessage('Supporting documents. PDF, Word or images, up to 10MB each.'),
    h6 : gs.getMessage('Check it over. Nothing is sent until you press submit.'),

    firstName    : gs.getMessage('First name'),
    middleName   : gs.getMessage('Middle name'),
    lastName     : gs.getMessage('Last name'),
    email        : gs.getMessage('Email'),
    phone        : gs.getMessage('Phone number'),
    birthdate    : gs.getMessage('Date of birth'),
    address      : gs.getMessage('Address'),
    street       : gs.getMessage('Street'),
    city         : gs.getMessage('City'),
    zip          : gs.getMessage('Zip or postal code'),
    country      : gs.getMessage('Country'),
    ssn          : gs.getMessage('Social security number'),
    ssnNote      : gs.getMessage('Required for individual applicants. Leave blank if you are applying as an organisation or a government body.'),
    citizenship  : gs.getMessage('Citizenship status'),
    gender       : gs.getMessage('Gender'),
    race         : gs.getMessage('Race'),
    ethnicity    : gs.getMessage('Ethnicity'),
    education    : gs.getMessage('Education level'),
    marital      : gs.getMessage('Marital status'),
    military     : gs.getMessage('Military status'),
    disability   : gs.getMessage('Disability status'),
    tribal       : gs.getMessage('Tribal affiliation'),
    whyAsk       : gs.getMessage('Why we ask'),
    whyAskText   : gs.getMessage('These answers are used for reporting on who the program reaches. Each list includes an option to withhold, and choosing it does not count against you.'),
    program      : gs.getMessage('Grant program'),
    category     : gs.getMessage('Category'),
    applicantType: gs.getMessage('Applicant type'),
    organisation : gs.getMessage('Organisation'),
    identityType : gs.getMessage('Identity type'),
    uei          : gs.getMessage('UEI'),
    tin          : gs.getMessage('TIN or EIN'),
    moneyTime    : gs.getMessage('Budget and timing'),

    dropTitle    : gs.getMessage('Drop your documents here'),
    dropText     : gs.getMessage('PDF, Word or image files, up to 10MB each'),
    chooseFiles  : gs.getMessage('Choose files'),
    remove       : gs.getMessage('Remove'),
    documents    : gs.getMessage('Documents'),
    filesAttached: gs.getMessage('files attached'),
    noFiles      : gs.getMessage('Nothing attached yet'),

    confirm      : gs.getMessage('The information above is accurate to the best of my knowledge.'),
    back         : gs.getMessage('Back'),
    continue     : gs.getMessage('Continue'),
    submit       : gs.getMessage('Submit application'),
    submitting   : gs.getMessage('Submitting'),

    eFirst      : gs.getMessage('First name is required'),
